def calculate_profit(a: List[int]) -> int:
    import sys

    n = len(a)
    total_profit = sum(a)
    priority_queue = nsmallest(n-1, a)

    for i in range(n-1, -1, -1):
        total_profit -= priority_queue[i]
    a.sort()

    balance = total_profit // 2 if total_profit % 2 == 0 else (total_profit // 2) + 1
    take_from_right = sum(a[:n-1]) - balance
    take_from_left = sum(a[-1:]) - balance if take_from_right > 0 else 0

    # Absolute difference to get the highest optimal difference
    return int(abs(take_from_right - take_from_left))

