from collections import defaultdict

def find_center(segment):
    sorted_segment = sorted(segment)
    mid = (len(segment) + 1) // 2
    if len(segment) % 2 == 0:
        mid = (len(segment) + 2) // 2
    return sorted_segment[mid - 1]

def calculate_strangeness(segment, i):
    return abs(find_center(segment) - i)

def calculate_strangeness_all_elements(n, elements):
    strangeness_map = defaultdict(int)
    for i, element in enumerate(elements):
        strangeness_map[element] = max(strangeness_map[element], calculate_strangeness(elements[i:], i))
    return list(strangeness_map.values())

