from collections import defaultdict, deque

def bfs(graph, start, visited):
    queue, distance = [], {}
    heapq.heappush(queue, (0, start))
    distance[start] = 0
    while queue:
        dist, vertex = heapq.heappop(queue)
        if vertex in visited:
            continue
        visited.add(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                distance[neighbor] = distance[vertex] + 1
                heapq.heappush(queue, (distance[neighbor], neighbor))
    return min(distance.values())

def is_strongly_connected(graph, start, sink):
    distance = bfs(graph, start, set())
    if sink not in distance:
        return False
    cycle = set()
    def detect_cycle(u, visited, cycle):
        if u in visited and u in cycle:
            return True
        visited.add(u)
        for neighbor in graph[u]:
            if detect_cycle(neighbor, visited, cycle):
                return True
        visited.remove(u)
        cycle.add(u)
        return False
    return not (detect_cycle(sink, set(), cycle))

