MOD = 998244353

def solve():
    def solve_xor_sum_values(n, values, mod):
        bit_counts = [0] * (n + 1)
        for value in values:
            bit_count = 0
            for i in range(32):
                if value >> i & 1:
                    bit_count += 1
            bit_counts[min(bit_count, n)] += 1
        ans = [0] * (n + 1)
        for i in range(n + 1):
            ans[i] = bit_counts[i] * i % mod
        return ans

    n, m = map(int, input().split())
    values = list(map(int, input().split()))

    # Part 1: Calculate the number of ways for values in range [0, n & (1 << m) - 1]
    len_ones = 2 ** m - 1
    ways = [[0] * (m + 1) for _ in range(n + 1)]
    ways[0] = [1] * m
    ways[1] = [1] + [0] * (m - 1)
    for i in range(2, n + 1):
        for j in range(m + 1):
            if j < max(0, len_ones - i // (1 << j)):
                ways[i][j] += ways[i - 1][j]
    # Adjust for negative len_ones
    if len_ones >= 1:
        ways[n][len_ones] = sum(ways[0]) % MOD

    # Part 2: Calculate the number of ways for specific x = 2^i
    # for specific j
    from functools import reduce
    def find_next_index(ones, ways):
        for i in range(len_ones, -1, -1):
            if ones < i:
                ones += i + 1
                yield i, ones

    for j in range((1 << m) - 1, -1, -1):
        ones = 2 * j + 1
        if ones > (1 << m):
            ones -= (1 << m)
            yield m, ones
        for i, ones_idx in find_next_index(ones, ways):
            ways[i][ones_idx] += reduce(lambda a, b: a * b % MOD, [ways[0][k], (2**k + 1) % MOD] for k in range(16))

    # Part 3: Sum up the number of ways for values in range [0, n & (1 << m) - 1]
    sum_ones = sum(*ways)
    mod_one = pow(n, sum_ones, MOD)

    for i in range(len_ones + 1):
        for j in range(len_ones + 2):
            if i >= 2 ** j:
                continue
            for p in range(1, 16):
                ways[i + 1][j] += ways[i][p] * comb(len_ones, j - p) % MOD

    post_cache_pushed = False
    def calc_value(i, j):
        if post_cache_pushed:
            return ways[i][j]
        ret = 0
        for pp in range(16):
            if i & (1 << pp):
                ret += comb(j, pp)
        ret = ret % MOD
        if j >= len_ones - pp:
            ret += pow(ways[0][j - len_ones + pp] * (j + 1), pp, MOD) % MOD
            if not post_cache_pushed:
                post_cache_pushed = True
            else:
                sum_ones &= (sum_ones + MODULE - MOD) % MOD
        return ret

    res = [pow(MODULE - 1 - calc_value(i, m), n // (1 << m), MOD) for i in range(m + 1)]
    return "\n".join(map(str, res))

