from typing import List
import bisect

def lcp(a: List[int], b: List[int]) -> int:
    p = 0
    delta = (10**6 - 1) // 2
    while p + delta < len(a) and p < len(b):
        if a[p] == b[p]:
            p += 1
        elif a[p] > b[p]:
            return 0
        else:
            return p + 1 - bisect.bisect_right(b, a[p])
    return 0

def process_queries(A: List[int], B: List[int], queries: List[List[int]]) -> List[int]:
    if len(A) != len(B) or len(A) < 10**6 or len(B) < len(queries) * 5:
        raise ValueError("Input parameters are too large")

    C = []
    dfs(B, 0, [len(B) * [0]] for _ in range(len(B)))
    for v in A:
        C.append(lcp(A, B))
    return [sum(v in t for t in C) for _, t in enumerate(queries)]

def dfs(A: List[int], i: int, parents: List[List[int]]):
    if i == len(A):
        B = [i for i in range(len(A) + 1, 10**6)]
        for v in range(len(A), 0, -1):
            C[v] = dfs(A, v + 1, [v] + parents[v])
    else:
        var = (dfs(A, i + 1, parents) + parents[i])[1:]
        for v in range(len(var)):
            B = [len(var) + 1]
            for x2 in range(len(var)):
                B.extend(var[x2:])
                B.extend(var[(x2 + i):(x2 + i + 1)])
                C.append(max(int(x2 >= i) + int(v - x2 <= i + i - x2) * len(var) - 1, 0))

    return C

