        visited[i] = True
        low[i] = stack.index(i)
        for neighbor in graph[i]:
            if visited[neighbor]:
                low[i] = min(low[i], low[neighbor])
            elif not neighbor in stack:
                dfs(graph, neighbor, low, visited, stack)
                low[i] = min(low[i], low[neighbor])
        if low[i] == stack.index(i):
            while True:
                x = stack.pop()
                visited[x] = True
                if x == i:
                    break
                stack.append(x)
