from collections import Counter

def count_palindromes(s, n):
    char_count = Counter(s)
    mid = int(len(s) / 2)
    pairs = {}
    for char, count in char_count.items():
        if count % 2 == 1:
            if char in pairs:
                pairs[char] += 1
            else:
                pairs[char] = 2
        elif count % 2 == 0:
            if char in pairs:
                pairs[char] = 2 - pairs.get(char, 0)

    results = [1]  # Single middle character
    for char, kind in pairs.items():
        this_cases = (1 << kind) - 1
        if kind > 1:
            for val in range(1, kind):
                this_cases = (this_cases * (1 << (1 - val))) % 10007
        results.append((1 < this_cases + 1) * this_cases % 10007)

    if n > len(s) // 2:
        return (len(s) + 1) * (1 << (len(s) // 2)) - n - 1

    return sum(results)

