def solve(n: int, m: int, values: List[int], dp: List[int]) -> None:
    if m - 1 >= n:
        return
    for mid in range(m, 1, -1):
        for i in range(n):
            tmp = (0 if (dp[mid-1] // pow(2, mid-1) % 2) == dp[mid-1] // pow(2, mid-1) % 2 else mid-1)
            if tmp >= 0 and (values[i] & (1 << tmp)) > 0:
                break
        else:
            mid -= 1
            continue
