from collections import defaultdict

def string_to_graph():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for _ in range(m):
        v, u = map(int, input().split())
        graph[v].append(u)
        in_degree[u] += 1

    return graph, in_degree

def is_path_exist(u, v, graph, in_degree):
    visited = [False] * (n + 1)
    stack = [u]

    while stack:
        node = stack.pop()
        if node in visited:
            continue

        visited[node] = True

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                stack.append(neighbor)

    return visited[v]

def remove_edge(graph, u, v):
    neighbors = graph[u]
    if v in neighbors:
        graph[u].remove(v)
    graph[v].remove(u)

def check_strong_connectivity(graph, in_degree):
    possible = []

    for u in range(1, n + 1):
        if all(in_degree[i] == 0 for i in range(1, n + 1) if u != i):
            possible.append(u)

    if not possible:
        return None

    s = possible.pop()
    t = possible[0]
    remove_edge(graph, s, t)

    for sink in possible[1:]:
        if is_path_exist(s, sink, graph, in_degree):
            return "YES"

    return "NO"

