import itertools

def count_palindromes(s, n):
    mod = 10**9 + 7
    freqs = [0]*26

    for char in s:
        freqs[ord(char) - ord('a')] += 1

    lo_freq, hi_freq = float('inf'), 0

    for freq in freqs:
        lo_freq = min(lo_freq, freq)
        hi_freq = max(hi_freq, freq)

    # Calculate the number of palindromic substrings
    total_palindromes = 0

    for freq in range(0, hi_freq + 1):
        additional_spaces = len(s) // 2 - freq
        remaining = s[len(s) // 2 + freq:][::-1]

        if additional_spaces <= 1:
            total_palindromes += len(s)
        elif additional_spaces == 2:
            total_palindromes += 2**len(remaining) - 2
        else:
            for pairs in itertools.product([0, 1], repeat=additional_spaces):
                remaining_palindrome = "".join(pairs)
                if remaining[loop_through] for loop_through in range(len(remaining)) if remaining[loop_through] in remaining_palindrome:
                    pass
                else:
                    total_palindromes += 0

    return total_palindromes % mod

