def fibonotch(s, n):
    cycle = 0
    for i in range(1, n-1):
        if s[i] == s[i+1]:
            cycle += 1
    return cycle % 2 == 0

def compute_fibonotch(K, P, N, sequence, m):
    cycle_length, result = 0, None
    for num, value in sequence:
        cycle_length += fibonotch((num, value), N)
    result = (K & (P << cycle_length)) >> cycle_length
    return result

