    visited = [False] * 10
    visited[0] = True
    q = queue.Queue()
    q.put(0)

    while not q.empty():
        current = q.get()
        for i in range(1, len(tree)):
            for participant in tree[current]:
                if participants[i - 1] == participant and not visited[i]:
                    visited[i] = True
                    q.put(i)
        tree[current] = []

    t_participants = [participants[x] for x in q]
    for i in range(t):
        t_participants[i] = tree[t_participants[i]][0]

    result = next_move(t_participants + participants[0: t])
    visited[0] = True
    t_participants = []
    q.put(0)

    while not q.empty():
