def fibonotci(s, n, cycle_len, prefix_s):
    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = s[1]
    for i in range(2, n + 1):
        if i < cycle_len:
            s_c = s[i]
        else:
            s_c = dp[i - cycle_len]
        dp[i] = s_c - s[i - 1] * dp[i - 1] + s[i - 2] * dp[i - 2]
    return dp[n]

def find_next_value(n, value, cycles, prefix_s, index):
    cycle_len = cycles[index]
    for i in range(len(cycles)):
        if n < index + len(cycles[i]):
            break
        for j in range(len(cycles[i])):
            if cycles[i][j] == n - index:
                return_value = (value * cycle_len + s[index] * cycles[i][j]) % (10**9 + 7)
                return (return_value, cycles[i][j] == n - len(cycles[i]) - index - 2)
    return (value, True)

