def count_palindromes(s, n):
    mod, count, odd_indices = 10007, 0, {}

    for i, char in enumerate(s):
        if char not in odd_indices:
            odd_indices[char] = i
            mod = mod * 24 + 1
            if ((i + 1) % 2 == 0 and (n - 1) % (2 * (i + 1)) >= 0) or (i % 2 == 0 and (n - 1) % (2 * (i + 1)) == 0):
                count = (count % mod) * mod % mod
                count += 1
                break
        else:
            count = (count % mod) * mod % mod
            count += 1

    return count % mod

