from collections import defaultdict

def is_strongly_connected(graph):
    indegrees = defaultdict(int)
    for vertex in graph:
        for neighbor in graph[vertex]:
            indegrees[neighbor] += 1

    queue = [vertex for vertex in graph if indegrees[vertex] == 0]
    while queue:
        v = queue.pop()
        for neighbor in graph[v]:
            indegrees[neighbor] -= 1
            if indegrees[neighbor] == 0:
                queue.append(neighbor)

    return all(value == 0 for value in indegrees.values())


def remove_edges(graph):
    sources = set()
    sinks = set()
    to_add = True
    while to_add:
        to_add = False
        for v in graph:
            if graph[v]:
                sources.add(v)
                graph[v] = set()
                to_add = True
        for v in graph:
            if graph[v]:
                sinks.add(v)
        for v in sources:
            graph[v][0] = sinks - {v}
            for source in graph[v]:
                graph[source][1] -= 1 if graph[source] else 1
        sources = sinks = set()
        for v in graph:
            graph[v] = list(graph[v])
