    def update(self, query_range, value):
        def update_range(i, start, end, x):
            if start == end:
                self.tree[i] = value
                return value
            mid = (start + end) // 2
            if range <= mid:
                self.tree[i] = update_range(2 * i + 1, start, mid, value)
            else:
                self.tree[i] = update_range(2 * i + 2, mid + 1, end, value)
            return self.tree[i]

        range = (query_range[1] - 1, query_range[1] + query_range[0])
        if range[0] <= range[1]:
